"""mangui guides, batch 12 (focused guides, 'partial': the most-used options and cases): git, docker, bash.
Examples teach (command + explanation); nothing is captured. Written by scripts/mangui_write.py."""

GUIDES = []

# ============================================================== git
GUIDES.append(dict(
    name="git", section="1", partial=True, one_line="distributed version control: track, share and recover changes",
    plain=["`git` records snapshots of a folder (called commits) so you can see what changed, go back to an earlier version, and share work with others. A folder tracked by git is a repository.",
           "The daily loop is: change files, `git add` the ones you want in the next snapshot (the staging area), `git commit` to record it, `git push` to send it to a server such as GitHub, `git pull` to bring others' work down.",
           "For security work git has a second use: repositories leak secrets. An old commit, a deleted file or a hidden .git folder on a web server often holds passwords and keys. This page is focused on the most-used commands and cases, not every option."],
    when=["Get a copy of a project (clone) and keep it up to date.", "Save your own work in steps and undo mistakes.", "Work on a feature in a branch and merge it.", "Search a repository's history for a leaked password or flag.", "Recover a deleted file."],
    examples=[("Copy a repository", "git clone https://github.com/user/project.git", "Downloads the whole project with its history into a folder named project."),
              ("See what has changed", "git status\ngit diff", "status lists changed and new files; diff shows the line-by-line changes not yet staged. git diff --staged shows what is staged."),
              ("Save a snapshot", "git add notes.md\ngit commit -m 'Add notes for web labs'", "add puts the file in the staging area, commit records it with a message. git add -A stages everything."),
              ("Send and receive", "git push origin main\ngit pull", "push uploads your commits to the remote called origin on branch main. pull downloads and merges new ones."),
              ("Look at history", "git log --oneline --graph --all", "One line per commit, with branches drawn. -p adds the changes; -n 5 limits the count."),
              ("Branch and merge", "git switch -c fix-typo\n# edit and commit\ngit switch main\ngit merge fix-typo", "switch -c creates and enters a branch. After committing there, go back to main and merge it in."),
              ("Undo carefully", "git restore notes.md\ngit restore --staged notes.md\ngit revert abc1234", "restore throws away uncommitted changes in a file; --staged unstages; revert adds a new commit that cancels an old one. These are the safe undo tools."),
              ("Park unfinished work", "git stash\ngit stash pop", "stash puts your uncommitted changes aside so you can switch branches; pop brings them back."),
              ("Hunt for a leaked secret", "git log -p --all -S 'password' -- .\ngit grep -i 'api_key' $(git rev-list --all)", "-S finds commits that added or removed that text. rev-list --all gives every commit to search. Also try git log --all --diff-filter=D --name-only to find deleted files."),
              ("Recover a hidden .git from a website (lab)", "wget -r http://10.10.10.5/.git/ && cd 10.10.10.5 && git checkout -- . && git log", "If a web server exposes /.git/, downloading it gives the whole project and history. Tools such as git-dumper automate this. Only on authorised targets."),
              ("Ignore files", "echo 'secrets.env' >> .gitignore", "Names in .gitignore are never added by accident. It does not remove a file that is already tracked.")],
    options=[
        ("clone URL [DIR]", "Copy a remote repository.", "Starting."),
        ("init", "Turn the current folder into a repository.", "New projects."),
        ("status [-s]", "Show changed, staged and untracked files (-s for short).", "Checking before commit."),
        ("add FILE... / -A / -p", "Stage files / everything / chosen parts of files.", "Choosing what goes in a commit."),
        ("commit -m MSG / -a / --amend", "Record a snapshot with a message / include tracked changes / redo the last commit.", "Saving."),
        ("diff [--staged] [A B]", "Show changes; compare two commits or branches.", "Reviewing."),
        ("log [--oneline] [--graph] [-p] [-n N] [--all] [-S TEXT] [-- PATH]", "Show history; search commits that changed TEXT; limit to a path.", "Investigation."),
        ("show COMMIT", "Show one commit and its changes.", "Reading a commit."),
        ("branch [-a] [-d NAME]", "List, list all, or delete branches.", "Branch management."),
        ("switch BRANCH / switch -c NEW", "Change to a branch / create and change.", "Moving around."),
        ("checkout BRANCH|COMMIT|-- FILE", "Older all-purpose command: change branch, inspect a commit, restore a file.", "Reading old guides."),
        ("merge BRANCH", "Combine another branch into the current one.", "Joining work."),
        ("rebase BRANCH", "Replay your commits on top of another branch.", "A cleaner history."),
        ("remote -v / add NAME URL", "List or add remote repositories.", "Linking to a server."),
        ("fetch / pull / push", "Download only / download and merge / upload.", "Syncing."),
        ("restore [--staged] FILE", "Discard changes or unstage.", "Undo."),
        ("reset [--soft|--mixed|--hard] COMMIT", "Move the branch pointer; --hard also overwrites files.", "Careful undo (hard loses work)."),
        ("revert COMMIT", "Make a new commit that undoes an old one.", "Safe undo of shared history."),
        ("stash [push|pop|list]", "Shelve and bring back uncommitted work.", "Context switching."),
        ("tag NAME", "Name a commit (a version).", "Releases."),
        ("grep PATTERN", "Search the files tracked by git.", "Fast code search."),
        ("blame FILE", "Show who last changed each line.", "Finding the origin of a line."),
        ("config --global user.name / user.email", "Set your identity for commits.", "First-time setup."),
        ("--help, git help COMMAND", "Open the manual for a command.", "Learning more.")],
    mistakes=["Committing secrets: a password pushed once stays in history even if you delete the file later. Rotate it.", "git reset --hard or git checkout -- . throws away uncommitted work with no undo.", "Force-pushing (git push --force) over other people's commits.", "Working directly on main when a branch would be safer.", "Forgetting git pull before starting and getting merge conflicts.", "Assuming .gitignore removes files already tracked: use git rm --cached."],
    try_=["Make a folder, git init, create two files and commit them separately.", "Create a branch, change a file, merge it back.", "Search a repo's history for the word 'password' with git log -S.", "Delete a file and bring it back with git restore."],
    see_also="gitignore(5), git-config(1), gitk(1), gh(1), git-dumper, truffleHog and gitleaks (secret scanners), and the free Pro Git book."))

# ============================================================== docker
GUIDES.append(dict(
    name="docker", section="1", partial=True, one_line="build and run containers (isolated, packaged applications)",
    plain=["A container is a lightweight, isolated box that holds a program and everything it needs. An image is the packaged recipe; a container is a running copy of an image. `docker` is the command that builds images and runs containers.",
           "Labs love it: one command starts a vulnerable machine, another deletes it, so your computer stays clean. This page is focused on the most-used commands, not every option.",
           "Security note: being in the docker group (or being able to run docker) is almost the same as being root on that host, because you can mount the host's folders into a container."],
    when=["Start a ready-made lab or tool (DVWA, Juice Shop, a Kali image).", "Run a command in an isolated environment.", "Build your own image from a Dockerfile.", "Copy files in and out of a container.", "Clean up unused containers and images."],
    examples=[("Run a container and get a shell", "docker run -it --rm ubuntu:24.04 bash", "-it gives an interactive terminal, --rm deletes the container when you exit. You are now in a fresh Ubuntu."),
              ("Run a web lab in the background", "docker run -d --name juice -p 3000:3000 bkimminich/juice-shop", "-d detaches, --name names it, -p 3000:3000 maps your port 3000 to the container's port 3000. Browse to http://localhost:3000."),
              ("What is running?", "docker ps\ndocker ps -a", "ps lists running containers; -a includes stopped ones."),
              ("Read logs", "docker logs -f juice", "-f follows new output like tail -f."),
              ("Get a shell in a running container", "docker exec -it juice sh", "exec runs a command inside an existing container; sh because many small images lack bash."),
              ("Stop and remove", "docker stop juice\ndocker rm juice", "stop ends it politely, rm deletes the container. docker rm -f does both."),
              ("Share a folder with the container", "docker run -it --rm -v \"$PWD\":/work -w /work ubuntu:24.04 bash", "-v host:container mounts your current folder at /work, -w sets the starting folder. Edits are visible on both sides."),
              ("Build an image", "docker build -t myimage .", "Reads the Dockerfile in the current folder and tags the result myimage."),
              ("Copy files", "docker cp juice:/etc/hosts ./hosts\ndocker cp ./note.txt juice:/tmp/", "cp moves files between your machine and a container."),
              ("Inspect and tidy", "docker inspect juice | head -40\ndocker image ls\ndocker system prune", "inspect prints settings and IP; image ls lists images; system prune removes unused containers, networks and dangling images (it asks first)."),
              ("Compose several containers", "docker compose up -d\ndocker compose down", "A docker-compose.yml describes a multi-container lab; up -d starts it, down removes it.")],
    options=[
        ("run [OPTIONS] IMAGE [CMD]", "Create and start a container.", "Starting anything."),
        ("-d, --detach", "Run in the background.", "Servers."),
        ("-it", "-i keep input open, -t give a terminal.", "Interactive shells."),
        ("--rm", "Delete the container when it exits.", "Throw-away runs."),
        ("--name NAME", "Give the container a name.", "Easy reference."),
        ("-p HOST:CONTAINER", "Publish a port.", "Reaching a service."),
        ("-v HOST:CONTAINER[:ro]", "Mount a folder or volume (read-only with :ro).", "Sharing files."),
        ("-e KEY=VALUE", "Set an environment variable.", "Configuring."),
        ("--network NAME / --net host", "Choose the network (host shares the host's network).", "Labs and scans."),
        ("-w DIR", "Working directory inside.", "Starting location."),
        ("-u USER", "Run as this user.", "Not root."),
        ("--privileged", "Give the container nearly all host rights.", "Rare, dangerous."),
        ("ps [-a]", "List containers.", "Seeing state."),
        ("images, image ls", "List images.", "Seeing what is downloaded."),
        ("pull IMAGE", "Download an image.", "Pre-loading."),
        ("exec [-it] CONTAINER CMD", "Run a command in a running container.", "Getting inside."),
        ("logs [-f] [--tail N] CONTAINER", "Show output.", "Debugging."),
        ("stop / start / restart CONTAINER", "Control a container.", "Management."),
        ("rm [-f] CONTAINER / rmi IMAGE", "Remove a container / image.", "Cleaning."),
        ("build -t NAME [-f FILE] PATH", "Build an image from a Dockerfile.", "Custom images."),
        ("cp SRC DEST", "Copy files between host and container.", "Moving files."),
        ("inspect NAME", "Show detailed JSON, including the IP address.", "Finding settings."),
        ("system prune [-a]", "Delete unused data.", "Reclaiming disk space."),
        ("compose up -d / down / logs", "Manage multi-container labs from a docker-compose.yml.", "Complex labs."),
        ("--help", "Help for any command: docker run --help.", "Looking up options.")],
    mistakes=["Forgetting --rm and filling the disk with stopped containers.", "Exposing a lab to the world with -p 0.0.0.0: use 127.0.0.1:3000:3000 for local-only.", "Expecting data to survive: container storage is deleted with the container unless you mount a volume.", "Using --privileged or mounting / without understanding that it hands over the host.", "Running docker without sudo and getting 'permission denied': add your user to the docker group (which is itself a privilege decision).", "Using :latest and getting a different image later."],
    try_=["Run ubuntu with -it --rm and check cat /etc/os-release.", "Start Juice Shop on port 3000 and stop it again.", "Mount your current folder into a container and create a file from inside.", "Run docker system df to see what takes space."],
    see_also="docker-compose(1), podman(1), kubectl(1), dive, trivy, and the Docker docs at docs.docker.com."))

# ============================================================== bash
GUIDES.append(dict(
    name="bash", section="1", partial=True, one_line="the GNU Bourne-Again shell (command interpreter)",
    plain=["`bash` is the program that reads what you type in the terminal and runs it. It also runs scripts: text files full of commands with variables, tests and loops.",
           "Much of CTF work is bash: chaining tools with pipes, looping over files or ports, and writing quick one-liners. This page is focused on the habits and syntax you use most, not every option of the very large bash manual."],
    when=["Chain commands with pipes and redirects.", "Loop over a list of hosts, files or numbers.", "Write a small script to automate a task.", "Use history and shortcuts to work fast.", "Run a one-liner with bash -c."],
    examples=[("Run a command and use its output", "echo \"Today is $(date +%F)\"", "$(...) runs a command and pastes its output in place (command substitution)."),
              ("Variables", "target=10.10.10.5\necho \"$target\"\nnmap -sV \"$target\"", "No spaces around =. Use $name to read it, and quote it so spaces do not break things."),
              ("Pipes and redirects", "cat access.log | grep 404 | wc -l\nls > files.txt\nls >> files.txt\ncmd 2> errors.txt\ncmd > all.txt 2>&1", "| feeds one command into the next; > overwrites; >> appends; 2> redirects errors; 2>&1 sends errors to the same place as output."),
              ("Loop over a list", "for ip in 10.10.10.{1..5}; do ping -c1 -W1 $ip >/dev/null && echo \"$ip up\"; done", "{1..5} expands to five addresses. && runs the echo only if ping succeeded."),
              ("Read a file line by line", "while read -r line; do echo \"[$line]\"; done < users.txt", "The loop runs once per line. -r keeps backslashes as they are."),
              ("A test and a branch", "if [ -f flag.txt ]; then cat flag.txt; else echo 'no flag'; fi", "[ ] is the test command; see man test for all the checks."),
              ("A small script", "#!/usr/bin/env bash\nset -euo pipefail\nfor f in \"$@\"; do echo \"== $f\"; file \"$f\"; done", "Save as check.sh, run chmod +x check.sh, then ./check.sh a b c. set -euo pipefail makes the script stop on errors and unset variables."),
              ("Run a string as bash", "bash -c 'echo $0 $1' name arg", "-c runs the string instead of a file; the words after it become $0, $1... Useful in xargs and cron."),
              ("History tricks", "!!   sudo !!   !$   Ctrl+R", "!! repeats the last command; sudo !! repeats it with sudo; !$ is its last word; Ctrl+R searches your history as you type."),
              ("Keyboard shortcuts", "Ctrl+A / Ctrl+E / Ctrl+W / Ctrl+U / Ctrl+L / Ctrl+C / Ctrl+D", "Start of line, end of line, delete word, delete to start, clear screen, interrupt, end of input (exit)."),
              ("Brace and glob expansion", "mkdir -p ctf/{web,pwn}/notes\nls *.txt\ncp file.{txt,bak}", "The shell expands braces and wildcards before the command sees them: file.{txt,bak} becomes file.txt file.bak.")],
    options=[
        ("-c STRING", "Run the commands in STRING.", "One-liners and cron."),
        ("-x", "Print each command before running it.", "Debugging scripts."),
        ("-e", "Stop on the first error.", "Safer scripts."),
        ("-u", "Treat unset variables as an error.", "Catching typos."),
        ("-o pipefail", "A pipeline fails if any command in it fails.", "Reliable scripts."),
        ("-n", "Read the script but do not run it (syntax check).", "Checking syntax."),
        ("-i", "Interactive shell.", "Starting a shell."),
        ("-l, --login", "Behave as a login shell.", "Environment loading."),
        ("-r", "Restricted shell.", "Locked-down accounts (and escaping them in CTFs)."),
        ("--norc / --noprofile", "Do not read ~/.bashrc / profile files.", "A clean shell."),
        ("-p", "Privileged mode: do not drop the effective user id.", "Setuid bash tricks in labs."),
        ("--version, --help", "Version and short help.", "A reminder."),
        ("Quoting: 'single' \"double\" \\escape", "Single quotes: nothing changes. Double quotes: variables and $(...) expand. Backslash escapes one character.", "Avoiding breakage."),
        ("Redirection: > >> < 2> &> <<< <<EOF", "Output, append, input, errors, both, here-string, here-document.", "Connecting files."),
        ("Pipes and lists: | && || ;  &", "Pipe, and-then, or-else, then, run in background.", "Chaining."),
        ("Expansions: $VAR ${VAR:-default} $(cmd) $((1+2)) {a,b} {1..5} *.txt ~", "Variables, defaults, command output, arithmetic, braces, ranges, wildcards, home folder.", "Everyday shortcuts."),
        ("Special variables: $? $$ $! $0 $1 $@ $#", "Last exit code, shell pid, last background pid, script name, arguments, all arguments, argument count.", "Scripting."),
        ("Control: if/elif/else/fi, for, while, until, case, function", "Branches, loops, matching, functions.", "Scripts."),
        ("Builtins: cd, export, alias, source, type, read, set, trap, jobs, fg, bg, history", "Shell-internal commands.", "Environment and job control."),
        ("Job control: Ctrl+Z, bg, fg, jobs, &", "Suspend, resume in background, resume in foreground, list, start in background.", "Several tasks."),
        ("Startup files: ~/.bashrc, ~/.profile, /etc/profile", "Run when the shell starts; put aliases and PATH changes here.", "Customising.")],
    mistakes=["Spaces around = in an assignment (a = 1 runs a command named a).", "Not quoting variables: a file called 'my file' becomes two arguments.", "Using [ $x = y ] when $x is empty or has spaces.", "Parsing ls output: use globs or find instead.", "Forgetting set -euo pipefail in scripts and missing failures.", "Writing scripts with Windows (CRLF) line endings: bash says ^M: bad interpreter.", "Running untrusted one-liners (curl | bash) without reading them."],
    try_=["Write a loop that pings 10.10.10.1 through 10.10.10.5 and prints the ones that answer.", "Write a script that takes file names and prints file's output for each.", "Use Ctrl+R to find a command you ran earlier.", "Redirect a command's errors to a file with 2> and read them."],
    see_also="test(1), echo(1), printf(1), find(1), xargs(1), sed(1), awk(1), grep(1), dash(1), zsh(1), and the Bash Reference Manual (info bash)."))
